"use client";
import type { ButtonHTMLAttributes } from "react";
import "./glitch-button.css";

export function GlitchButton({
  children,
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button {...props} type={type} className={`forme-glitch ${className}`}>
      <span className="forme-glitch-text">{children}</span>
      <span className="forme-glitch-layer" aria-hidden="true">
        {children}
      </span>
      <span className="forme-glitch-layer" aria-hidden="true">
        {children}
      </span>
    </button>
  );
}

.forme-glitch {
  --forme-glitch-a: #ff3d7f;
  --forme-glitch-b: #3de4ff;
  position: relative;
  display: inline-grid;
  height: 48px;
  padding: 0 26px;
  align-items: center;
  border: 1px solid #ffffff1a;
  border-radius: 999px;
  background: #0f0f11;
  box-shadow: inset 0 1px 0 #ffffff0f;
  color: #ededf0;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.005em;
  cursor: pointer;
  transition: border-color 0.2s;
}
.forme-glitch > span {
  grid-area: 1 / 1;
  white-space: nowrap;
}
.forme-glitch-layer {
  opacity: 0;
  mix-blend-mode: screen;
}
.forme-glitch-layer:nth-child(2) {
  color: var(--forme-glitch-a);
}
.forme-glitch-layer:nth-child(3) {
  color: var(--forme-glitch-b);
}
.forme-glitch:hover,
.forme-glitch:focus-visible {
  border-color: #ffffff38;
}
/* One short burst per arrival, then the label settles. */
.forme-glitch:hover .forme-glitch-layer:nth-child(2),
.forme-glitch:focus-visible .forme-glitch-layer:nth-child(2) {
  animation: forme-glitch-a 0.42s steps(1, end) 1;
}
.forme-glitch:hover .forme-glitch-layer:nth-child(3),
.forme-glitch:focus-visible .forme-glitch-layer:nth-child(3) {
  animation: forme-glitch-b 0.42s steps(1, end) 1;
}
.forme-glitch:hover .forme-glitch-text,
.forme-glitch:focus-visible .forme-glitch-text {
  animation: forme-glitch-text 0.42s steps(1, end) 1;
}
.forme-glitch:active {
  transform: scale(0.98);
}
.forme-glitch:focus-visible {
  outline: 2px solid #ededf0;
  outline-offset: 3px;
}
.forme-glitch:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@keyframes forme-glitch-a {
  0% { opacity: 1; clip-path: inset(12% 0 58% 0); transform: translate(-3px, 0); }
  20% { clip-path: inset(62% 0 8% 0); transform: translate(2px, 0); }
  40% { clip-path: inset(30% 0 44% 0); transform: translate(-2px, 0); }
  60% { clip-path: inset(4% 0 80% 0); transform: translate(3px, 0); }
  80% { clip-path: inset(48% 0 24% 0); transform: translate(-1px, 0); }
  100% { opacity: 0; }
}
@keyframes forme-glitch-b {
  0% { opacity: 1; clip-path: inset(58% 0 14% 0); transform: translate(3px, 0); }
  20% { clip-path: inset(14% 0 62% 0); transform: translate(-2px, 0); }
  40% { clip-path: inset(44% 0 30% 0); transform: translate(2px, 0); }
  60% { clip-path: inset(78% 0 4% 0); transform: translate(-3px, 0); }
  80% { clip-path: inset(22% 0 52% 0); transform: translate(1px, 0); }
  100% { opacity: 0; }
}
@keyframes forme-glitch-text {
  0%, 60% { opacity: 0.55; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .forme-glitch-layer,
  .forme-glitch-text {
    animation: none !important;
  }
  .forme-glitch:active {
    transform: none;
  }
}
